// SPDX-License-Identifier:MIT
pragma solidity ^0.8.26;

interface IFeeController {
    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃     Structs / Enums       ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Enum representing the type of fee.
    enum FeeType {
        Deposit,
        Withdraw,
        Reward
    }

    /// @notice Struct containing fee configuration parameters.
    /// @param feeType The type of fee being applied.
    /// @param feePercentage The fee percentage in basis points (1% = 100).
    struct FeeConfig {
        FeeType feeType;
        uint256 feePercentage;
    }

    // ┏━━━━━━━━━━━━━━━━━┓
    // ┃    Errors       ┃
    // ┗━━━━━━━━━━━━━━━━━┛

    /// @notice Thrown when the specified fee percentage exceeds the allowed maximum limit.
    error FeePercentageExceedLimit();

    /// @notice Thrown when a provided address is the zero address.
    error ZeroAddressNotValid();

    /// @notice Thrown when no oracle exists for the specified token.
    error NoOracleExist();

    /// @notice Thrown when an array length is invalid or does not match the expected length.
    error InvalidArrayLength();

    // ┏━━━━━━━━━━━━━━━━━━┓
    // ┃     Events       ┃
    // ┗━━━━━━━━━━━━━━━━━━┛

    /// @notice Emitted when a new fee configuration is set for a function selector.
    /// @param selector The function selector.
    /// @param feeType The type of fee applied.
    /// @param feePercentage The fee percentage in basis points.
    event FeeConfigSet(bytes4 indexed selector, FeeType feeType, uint256 feePercentage);

    /// @notice Emitted when a token getter contract is set for a target contract and function selector.
    /// @param target The target contract address.
    /// @param selector The function selector.
    /// @param tokenGetter The address of the token getter contract.
    event TokenGetterSet(address indexed target, bytes4 indexed selector, address tokenGetter);

    /// @notice Emitted when a global fallback token getter is set for a function selector.
    /// @param selector The function selector.
    /// @param tokenGetter The address of the global token getter contract.
    event GlobalTokenGetterSet(bytes4 indexed selector, address tokenGetter);

    /// @notice Emitted when a minimum fee amount in USD is set for a specific fee type.
    /// @param feeType The fee type.
    /// @param minFeeUSD The minimum fee amount in USD (18 decimals).
    event MinFeeSet(FeeType feeType, uint256 minFeeUSD);

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃            Admin Functions          ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Sets the fee configuration for a specific function selector.
    /// @param selector Function selector to configure the fee for.
    /// @param feeType Type of fee (Deposit, Withdraw, Reward).
    /// @param feePercentage Fee percentage in basis points (max 10000).
    function setFunctionFeeConfig(bytes4 selector, FeeType feeType, uint256 feePercentage) external;

    /// @notice Sets a token getter contract for a specific target contract and function selector.
    /// @param selector Function selector for which the token getter is set.
    /// @param tokenGetter Address of the token getter contract.
    /// @param target Target contract address where the selector is used.
    function setTokenGetter(bytes4 selector, address tokenGetter, address target) external;

    /// @notice Sets a global fallback token getter contract for a specific function selector.
    /// @param selector Function selector for which the global token getter is set.
    /// @param tokenGetter Address of the token getter contract.
    function setGlobalTokenGetter(bytes4 selector, address tokenGetter) external;

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃          View / Utility             ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Retrieves the token address associated with a function call on a target contract.
    /// @dev Uses a specific token getter if available, otherwise falls back to a global one.
    /// @param target Target contract address.
    /// @param selector Function selector of the target function.
    /// @param params Encoded parameters for the token getter to use.
    /// @return token Address of the token used for fee payment.
    /// @return exists Boolean indicating if a token getter was found.
    function getTokenForAction(address target, bytes4 selector, bytes memory params)
        external
        view
        returns (address, bool);

    /// @notice Calculates the applicable fee amount for a given token, function selector, and volume.
    /// @dev Returns the higher of the calculated fee or the configured minimum fee in USD.
    /// @param token Address of the token being charged.
    /// @param selector Function selector for which the fee is being calculated.
    /// @param volume Transaction volume (usually token amount).
    /// @return The applicable fee amount denominated in USD (18 decimals).
    function calculateFee(address token, bytes4 selector, uint256 volume) external view returns (uint256);

    /// @notice Converts a fee denominated in USD to its equivalent token amount.
    /// @param token Address of the token.
    /// @param feeInUSD Fee amount in USD (18 decimals).
    /// @return Equivalent token amount based on the oracle price.
    function calculateTokenAmount(address token, uint256 feeInUSD) external view returns (uint256);

    /// @notice Returns the address of the token getter contract used for a specific target and selector.
    /// @param target Target contract address.
    /// @param selector Function selector.
    /// @return Address of the token getter contract (or zero address if none found).
    function tokenGetter(address target, bytes4 selector) external view returns (address);

    /// @notice Returns the fee configuration for a given function selector.
    /// @param selector Function selector.
    /// @return The FeeConfig struct associated with the selector.
    function functionFeeConfig(bytes4 selector) external view returns (FeeConfig memory);

    /// @notice Returns the maximum allowed fee percentage for a specific FeeType.
    /// @param feeType FeeType enum value.
    /// @return Maximum fee percentage allowed.
    function maxFeeLimit(FeeType feeType) external view returns (uint256);

    /// @notice Returns the minimum fee amount in USD for a specific FeeType.
    /// @param feeType FeeType enum value.
    /// @return Minimum fee in USD (18 decimals).
    function minFeeInUSD(FeeType feeType) external view returns (uint256);

    /// @notice Checks if a given token has an associated price oracle.
    /// @param token Address of the token.
    /// @return Boolean indicating if an oracle exists for the token.
    function hasOracle(address token) external view returns (bool);

    /// @notice Returns the address of the configured price oracle.
    /// @return Address of the oracle contract.
    function priceOracle() external view returns (address);
}

contracts/interfaces/IFeeHandler.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

interface IFeeHandler {
    // ┏━━━━━━━━━━━━━━━━━┓
    // ┃    Errors       ┃
    // ┗━━━━━━━━━━━━━━━━━┛

    error InvalidAmount();
    error ZeroAddressNotValid();
    error InvalidBeneficiary();
    error PrimaryTokenAlreadyActivated();
    error InvalidPercentageDistribution();
    error TokenNotAllowed();
    error InvalidPercentage();

    // ┏━━━━━━━━━━━━━━━━━━┓
    // ┃     Events       ┃
    // ┗━━━━━━━━━━━━━━━━━━┛

    event FeeHandled(
        address indexed token,
        uint256 totalFee,
        address beneficiary,
        address creator,
        uint256 beneficiaryFee,
        uint256 creatorFee,
        uint256 vaultFee,
        uint256 burnAmount
    );
    event FeeHandledETH(
        uint256 totalFee,
        address beneficiary,
        address creator,
        uint256 beneficiaryFee,
        uint256 creatorFee,
        uint256 vaultFee,
        uint256 burnAmount
    );
    event PrimaryTokenActivated(address token, address treasury, uint256 primaryTokenBurn, uint256 tokenBurn);
    event UpdatedVault(address vault);
    event UpdatedBurnerAddress(address burnerAddress);
    event UpdatedPercentages(uint256 beneficiary, uint256 creator, uint256 vault);
    event UpdatedTokenAllowance(address token, bool allowed);
    event UpdatedReduction(address reduction);
    event Withdrawn(address indexed receiver, address indexed token, uint256 amount);

    /// @notice Handles ERC20 fee payment. Stores receivable amounts for beneficiary, creator, and vault.
    /// @param token The token address used for payment.
    /// @param amount The total fee amount sent by the user.
    /// @param beneficiary The fee beneficiary address.
    /// @param creator Optional creator address to receive part of the fee.
    /// @return totalAmount Total fee + burn amount recorded.
    function handleFee(address token, uint256 amount, address beneficiary, address creator)
        external
        returns (uint256);

    /// @notice Handles native ETH fee payment. Stores receivable ETH for withdrawal.
    /// @param beneficiary The fee beneficiary address.
    /// @param creator Optional creator address.
    /// @return totalAmount Total fee + burn amount recorded.
    function handleFeeETH(address beneficiary, address creator) external payable returns (uint256);

    /// @notice Allows a user to withdraw their accumulated fee balance for a given token.
    /// @param token The token address to withdraw (use address(0) for ETH).
    function withdraw(address token) external;

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃            Admin Functions          ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Activates primary token for fee discounts.
    /// @param token Address of the primary token.
    /// @param treasury Address of the treasury.
    /// @param primaryTokenBurn The percenetage of primary token discount.
    /// @param primaryTokenBurn The percenetage of primary token burned.
    /// @param tokenBurn The percentage of token burned.
    function activatePrimaryToken(
        address token,
        address treasury,
        uint256 primaryTokenDiscount,
        uint256 primaryTokenBurn,
        uint256 tokenBurn
    ) external;

    /// @notice Updates vault address.
    /// @param vault New vault address.
    function updateVault(address vault) external;

    /// @notice Updates reduction contract address.
    /// @param reduction New reduction contract address.
    function updateReduction(address reduction) external;

    /// @notice Updates fee distribution percentages.
    /// @param beneficiary Beneficiary percentage.
    /// @param creator Creator percentage.
    /// @param vault Vault percentage.
    function updatePercentages(uint256 beneficiary, uint256 creator, uint256 vault) external;

    /// @notice Updates token allowance for fee payment.
    /// @param token Token address.
    /// @param allowed Boolean indicating if the token is allowed.
    function updateTokenAllowance(address token, bool allowed) external;

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃          View / Utility             ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Returns true if a primary token is active.
    /// @return active Boolean indicating if primary token is active.
    function primaryTokenActive() external view returns (bool);

    /// @notice Returns true if a token is allowed for payment.
    /// @param token Token address.
    /// @return allowed Boolean indicating if token is allowed.
    function tokenAllowed(address token) external view returns (bool);

    /// @notice Returns the withdrawable balance for a given user and token.
    /// @param user The address of the user.
    /// @param token The token address (use address(0) for ETH).
    /// @return balance The amount the user can withdraw.
    function getWithdrawableBalance(address user, address token) external view returns (uint256 balance);
}

contracts/interfaces/IStrategyBuilderMod.content:
// SPDX-License-Identifier:MIT
pragma solidity ^0.8.26;

interface IStrategyBuilderModule {
    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃     Structs / Enums       ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    enum FunctionId {
        USER_OP_VALIDATION_SESSION_KEY
    }

    /// @dev Enum for different types of actions in the strategy.
    /// @notice Enum representing the type of action in an automation strategy.
    enum ActionType {
        EXTERNAL, // External action interacting with external contracts.
        INTERNAL_ACTION // Internal action interacting with IAction contracts.

    }

    /// @dev Struct representing a single action in a strategy.
    /// @notice Defines an action to be executed as part of a strategy, including the selector, parameters, target address, value, and action type.
    struct Action {
        bytes4 selector; // The function selector for the action.
        bytes parameter; // The parameters to be passed to the action.
        address target; // The target address to which the action is directed.
        uint256 value; // The value (in wei) to be sent along with the action.
        ActionType actionType; // The type of action (external or internal).
        ContextKey[] inputs;
        ContextKey output;
        uint8 result;
    }

    struct ContextKey {
        bytes32 key;
        Parameter parameterReplacement;
    }

    struct Parameter {
        uint256 offset; // Byte offset in parameter where replacement happens
        uint256 length; // Length of data to replace (32 for uint256, 20 for address)
        ParamType paramType; // Type of parameter being replaced
    }

    enum ParamType {
        UINT256,
        ADDRESS,
        BYTES32,
        BOOL
    }

    struct ActionContext {
        mapping(bytes32 => bytes) variables;
        mapping(bytes32 => address) addresses;
        mapping(bytes32 => uint256) amounts;
        mapping(bytes32 => bool) booleans;
    }

    /// @dev Struct defining a condition that must be met for a strategy or automation to be executed.
    /// @notice Represents a condition that will determine the execution flow in a strategy.
    struct Condition {
        address conditionAddress; // The address of the contract providing the condition.
        uint32 id; // The ID of the condition.
        uint8 result1; // The index to jump to if the condition returns 1.
        uint8 result0; // The index to jump to if the condition returns 0.
    }

    /// @dev Struct representing a single step in a strategy.
    /// @notice A strategy step includes a condition and associated actions to be executed.
    struct StrategyStep {
        Condition condition; // The condition that check if the actions in this step should executed.
        Action[] actions; // An array of actions to be executed if the condition is met.
    }

    /// @dev Struct representing a strategy, consisting of multiple steps.
    /// @notice Defines a strategy with its creator and the series of steps that make up the strategy.
    struct Strategy {
        address creator; // The address of the creator of the strategy.
        StrategyStep[] steps; // The steps that make up the strategy.
        bytes32 contextId;
    }

    /// @dev Struct representing an automation process that can be executed based on a condition.
    /// @notice Defines an automation linked to a strategy, with a condition and payment details.
    struct Automation {
        Condition condition; // The condition that must return 1 for the automation to execute.
        uint32 strategyId; // The ID of the strategy associated with the automation.
        address paymentToken; // The token used to pay the execution fees.
        uint256 maxFeeAmount; // The maximum fee amount the user is willing to pay in the automation.
    }

    // ┏━━━━━━━━━━━━━━━━━┓
    // ┃    Errors       ┃
    // ┗━━━━━━━━━━━━━━━━━┛

    error InvalidID();
    error StrategyDoesNotExist();
    error StrategyAlreadyExist();
    error AutomationNotExecutable(address condition, uint32 id);
    error FeeExceedMaxFee();
    error AutomationNotExist();
    error AutomationAlreadyExist();
    error StrategyIsInUse();
    error changeAutomationInConditionFailed();
    error ChangeStrategyInConditionFailed();
    error UpdateConditionFailed(address condition, uint32 id);
    error PaymentTokenNotAllowed();
    error InvalidNextStepIndex();
    error InvalidStepArrayLength();
    error InvalidActionTarget();
    error InvalidConditionAddress();
    error InvalidCondition();
    error PluginExecutionFailed();
    error NoConditionOrActions(uint256 stepIndex);
    error InvalidContextKey();

    // ┏━━━━━━━━━━━━━━━━━━┓
    // ┃     Events       ┃
    // ┗━━━━━━━━━━━━━━━━━━┛

    /**
     * @notice Emitted when the global feesEnabled flag is toggled
     * @dev Allows off-chain monitoring of fee payment availability across all executions
     * @param enabled True if fees are now enabled, false if disabled
     */
    event FeesEnabled(bool enabled);

    /// @notice Event emitted when a strategy is created.
    /// @param wallet The address of the wallet that created the strategy.
    /// @param strategyId The unique ID of the created strategy.
    /// @param creator The address of the strategy creator.
    /// @param strategy The details of the created strategy.
    /// @param contextId The used context for the strategy
    event StrategyCreated(
        address indexed wallet, uint32 strategyId, address creator, bytes32 contextId, Strategy strategy
    );

    /// @notice Event emitted when a strategy is executed.
    /// @param wallet The address of the wallet executing the strategy.
    /// @param strategyId The unique ID of the strategy being executed.
    event StrategyExecuted(address indexed wallet, uint32 strategyId);

    /// @notice Event emitted when a strategy is deleted.
    /// @param wallet The address of the wallet that deleted the strategy.
    /// @param strategyId The unique ID of the deleted strategy.
    event StrategyDeleted(address indexed wallet, uint32 strategyId);

    /// @notice Event emitted when an automation is created.
    /// @param wallet The address of the wallet creating the automation.
    /// @param automationId The unique ID of the created automation.
    /// @param strategyId The ID of the strategy associated with the automation.
    /// @param condition The condition that must be met for the automation to execute.
    /// @param paymentToken The token used to pay the execution fees.
    /// @param maxFeeAmount The maximum fee the user is willing to pay.
    event AutomationCreated(
        address indexed wallet,
        uint32 automationId,
        uint32 strategyId,
        Condition condition,
        address paymentToken,
        uint256 maxFeeAmount
    );

    /// @notice Event emitted when an automation is deleted.
    /// @param wallet The address of the wallet that deleted the automation.
    /// @param automationId The unique ID of the deleted automation.
    event AutomationDeleted(address indexed wallet, uint32 automationId);

    /// @notice Event emitted when an automation is executed.
    /// @param wallet The address of the wallet executing the automation.
    /// @param automationId The unique ID of the automation being executed.
    /// @param paymentToken The token used to pay for the execution.
    /// @param feeInToken The amount of tokens paid for execution.
    /// @param feeInUSD The value of the fee in USD.
    event AutomationExecuted(
        address indexed wallet, uint32 automationId, address paymentToken, uint256 feeInToken, uint256 feeInUSD
    );

    /// @notice Event emitted when a strategy step is executed.
    /// @param wallet The address of the wallet executing the strategy step.
    /// @param strategyId The unique ID of the strategy being executed.
    /// @param stepId The ID of the step being executed.
    /// @param actions The list of actions executed as part of the step.
    event StrategyStepExecuted(address indexed wallet, uint32 strategyId, uint32 stepId, Action[] actions);

    /// @notice Event emitted when an action is executed.
    /// @param wallet The address of the wallet executing the action.
    /// @param action The details of the action being executed.
    event ActionExecuted(address indexed wallet, Action action);

    event ContextVariableStored(bytes32 indexed contextId, bytes32 key, bytes result);

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃     Public Functions       ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Enables fee calculations and payments for all strategy and automation executions
    ///  @dev Only callable by contract owner/admin. Restores normal fee processing after disablement.
    ///      Emits FeesEnabled event with true parameter.
    function enableFees() external;

    /// @notice Disables fee calculations and payments for all strategy and automation executions
    /// @dev Only callable by contract owner/admin. All actions execute without fees when disabled.
    ///      Useful for emergency pauses, testing, or promotional zero-fee periods.
    ///      Emits FeesEnabled event with false parameter.
    function disableFees() external;

    /// @notice Creates a new strategy with a given ID, creator address, and strategy steps.
    /// @dev The strategy is stored in a mapping using a bytes32 key generated from the strategy ID and msg.sender.
    /// @param id The unique identifier for the strategy.
    /// @param creator The address of the strategy creator.
    /// @param steps An array of StrategyStep structs defining the sequence of actions and conditions in the strategy.
    function createStrategy(uint32 id, address creator, StrategyStep[] calldata steps) external;

    function createStrategyWithExistingContext(
        uint32 id,
        address creator,
        StrategyStep[] calldata steps,
        bytes32 contextId
    ) external;

    /// @notice Deletes a strategy associated with the caller's address and the given strategy ID.
    /// @dev Removes the strategy with the specified ID, ensuring the caller is the owner of the strategy.
    /// @param id The unique ID of the strategy to be deleted.
    function deleteStrategy(uint32 id) external;

    /// @notice Executes the strategy associated with the given strategy ID.
    /// @dev Triggers the execution of the strategy identified by the provided ID.
    /// @param id The unique ID of the strategy to be executed.
    function executeStrategy(uint32 id) external;

    /// @notice Creates a new automation linked to an existing strategy with specified execution conditions.
    /// @dev Stores an Action struct that references a strategy and defines a trigger condition for automated execution.
    /// @param id The user-defined identifier for the automation.
    /// @param strategyId The ID of the existing strategy this automation will execute.
    /// @param paymentToken The token address used to pay for execution fees.
    /// @param maxFeeInUSD The maximum fee (denominated in USD) the user is willing to pay for automation execution.
    /// @param condition The trigger condition that must be met to execute the strategy.
    function createAutomation(
        uint32 id,
        uint32 strategyId,
        address paymentToken,
        uint256 maxFeeInUSD,
        Condition calldata condition
    ) external;

    /// @notice Deletes an automation associated with the caller's address and the given automation ID.
    /// @dev Removes the automation with the specified ID, ensuring the caller is the owner of the automation.
    /// @param id The unique ID of the automation to be deleted.
    function deleteAutomation(uint32 id) external;

    /// @notice Executes an existing automation for a specific wallet and distributes fees.
    /// @dev Executes the strategy linked to the given automation ID if the condition is met.
    ///      A portion of the execution fee is sent to the specified beneficiary address.
    /// @param id The ID of the automation to execute.
    /// @param wallet The address for which the automation should be executed (the strategy owner).
    /// @param beneficary The address that will receive a portion of the execution fees as a reward.
    function executeAutomation(uint32 id, address wallet, address beneficary) external;

    /// @notice Stores or updates a typed variable in the caller's global context
    /// @dev Validates non-empty key and stores value with type-specific handling for efficient retrieval.
    ///      Raw bytes always stored; typed mappings populated when possible. Emits ContextVariableStored event.
    /// @param contextId Unique identifier for the strategy's shared context
    /// @param key Non-empty string identifier for the context variable
    /// @param paramType Expected data type for storage and subsequent retrieval
    /// @param value Raw bytes value to store in the context
    function storeConextVariable(bytes32 contextId, bytes32 key, ParamType paramType, bytes memory value) external;

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃     View Functions      ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Retrieves the strategy associated with the given wallet and strategy ID.
    /// @dev Returns the strategy details stored for the specified wallet and strategy ID.
    /// @param wallet The address of the wallet whose strategy is being retrieved.
    /// @param id The unique ID of the strategy to be fetched.
    /// @return The Strategy struct associated with the given wallet and ID.
    function strategy(address wallet, uint32 id) external view returns (Strategy memory);

    /// @notice Retrieves the automation associated with the given wallet and automation ID.
    /// @dev Returns the automation details stored for the specified wallet and automation ID.
    /// @param wallet The address of the wallet whose automation is being retrieved.
    /// @param id The unique ID of the automation to be fetched.
    /// @return The Automation struct associated with the given wallet and ID.
    function automation(address wallet, uint32 id) external view returns (Automation memory);

    /// @notice Computes a unique storage identifier based on the given wallet and ID.
    /// @dev Returns a `bytes32` identifier derived from the wallet address and ID, useful for referencing strategy or automation storage.
    /// @param wallet The address of the wallet to be included in the storage ID calculation.
    /// @param id The unique ID to be included in the storage ID calculation.
    /// @return A unique `bytes32` storage identifier based on the wallet address and ID.
    function getStorageId(address wallet, uint32 id) external pure returns (bytes32);

    /// @notice Retrieves a stored context variable value as raw bytes
    /// @dev Returns the raw bytes value from the variables mapping for a given context and key
    ///      For type-specific access, use dedicated view functions or off-chain ABI decoding
    ///      Empty bytes returned if variable doesn't exist in the specified context
    /// @param wallet Address of the modular account owning the context
    /// @param contextId Identifier of the strategy context containing the variable
    /// @param key  identifier of the specific context variable to retrieve
    /// @return value Raw bytes value stored for the specified key, or empty bytes if not set
    function getContextVariable(address wallet, bytes32 contextId, bytes32 key) external view returns (bytes memory);
}

contracts/StrategyBuilderModule.sol.content:
// SPDX-License-Identifier:MIT
pragma solidity ^0.8.28;

import {
    IExecutionModule,
    ExecutionManifest,
    ManifestExecutionFunction
} from "@erc6900/reference-implementation/interfaces/IExecutionModule.sol";
import {IModularAccount} from "@erc6900/reference-implementation/interfaces/IModularAccount.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IStrategyBuilderModule} from "./interfaces/IStrategyBuilderModule.sol";
import {ICondition} from "./interfaces/ICondition.sol";
import {IFeeController} from "./interfaces/IFeeController.sol";
import {IFeeHandler} from "./interfaces/IFeeHandler.sol";
import {IActionRegistry} from "./interfaces/IActionRegistry.sol";
import {IAction} from "./interfaces/IAction.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC165} from "@openzeppelin/contracts/utils/introspection/IERC165.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title StrategyBuilderModule
 * @dev A moodule for creating, executing, and managing automated strategies based on predefined conditions and actions.
 */
contract StrategyBuilderModule is ReentrancyGuard, Ownable, IStrategyBuilderModule, IExecutionModule {
    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃       StateVariable       ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Fee controller contract
    IFeeController public immutable feeController;

    /// @notice Fee handler contract
    IFeeHandler public immutable feeHandler;

    /// @notice Action Registry contract
    IActionRegistry public immutable actionRegistry;

    /// @notice Global flag controlling whether fee calculations and payments are enabled
    /// @dev Defaults to true; can be toggled by owner for testing or promotional periods
    bool public feesEnabled = true;

    /// @notice Maps strategy IDs to strategy data
    mapping(bytes32 => Strategy) private strategies;

    /// @notice Tracks where each strategy is used
    mapping(bytes32 => uint32[]) private strategiesUsed;

    /// @notice Maps automation IDs to their index in the owner's strategy usage array
    mapping(bytes32 => uint32) private automationsToIndex; //Maps each automation ID to its index in the owner's used strategy array.

    /// @notice Maps automation IDs to automation data
    mapping(bytes32 => Automation) private automations;

    mapping(address => mapping(bytes32 => ActionContext)) private globalContexts;

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃       Modifier            ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    modifier strategyExist(address wallet, uint32 id) {
        if (strategies[getStorageId(wallet, id)].steps.length == 0) {
            revert StrategyDoesNotExist();
        }
        _;
    }

    modifier strategyDoesNotExist(address wallet, uint32 id) {
        if (strategies[getStorageId(wallet, id)].steps.length > 0) {
            revert StrategyAlreadyExist();
        }
        _;
    }

    modifier automationExist(address wallet, uint32 id) {
        if (automations[getStorageId(wallet, id)].condition.conditionAddress == address(0)) {
            revert AutomationNotExist();
        }
        _;
    }

    modifier automationDoesNotExist(address wallet, uint32 id) {
        if (automations[getStorageId(wallet, id)].condition.conditionAddress != address(0)) {
            revert AutomationAlreadyExist();
        }
        _;
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃       Constructor         ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Deploys the StrategyBuilder contract with the given fee controller and fee handler.
    /// @dev Sets the addresses for fee management contracts.
    /// @param _feeController Address of the contract responsible for fee configuration and validation.
    /// @param _feeHandler Address of the contract responsible for fee distribution and handling.
    /// @param _actionRegistry The address of the ActionRegistry contract used to validate allowed action contracts.
    constructor(address _feeController, address _feeHandler, address _actionRegistry) Ownable(msg.sender) {
        feeController = IFeeController(_feeController);
        feeHandler = IFeeHandler(_feeHandler);
        actionRegistry = IActionRegistry(_actionRegistry);
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃    Admin functions    ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Enable fee payments
    /// @dev Only callable by owner/admin if using access control
    function enableFees() external onlyOwner {
        // Optional: require(msg.sender == owner, "Unauthorized");
        feesEnabled = true;
        emit FeesEnabled(true);
    }

    /// @notice Disable fee payments
    /// @dev Only callable by owner/admin if using access control
    function disableFees() external onlyOwner {
        // Optional: require(msg.sender == owner, "Unauthorized");
        feesEnabled = false;
        emit FeesEnabled(false);
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃    Execution functions    ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @inheritdoc IStrategyBuilderModule
    function createStrategy(uint32 id, address creator, StrategyStep[] calldata steps)
        external
        strategyDoesNotExist(msg.sender, id)
    {
        _createStrategy(id, creator, steps, bytes32(0));
    }

    function createStrategyWithExistingContext(
        uint32 id,
        address creator,
        StrategyStep[] calldata steps,
        bytes32 contextId
    ) external strategyDoesNotExist(msg.sender, id) {
        _createStrategy(id, creator, steps, contextId);
    }

    /// @inheritdoc IStrategyBuilderModule
    function deleteStrategy(uint32 id) external strategyExist(msg.sender, id) {
        bytes32 storageId = getStorageId(msg.sender, id);

        if (strategiesUsed[storageId].length > 0) {
            revert StrategyIsInUse();
        }

        Strategy memory _strategy = strategies[storageId];

        for (uint256 i = 0; i < _strategy.steps.length; i++) {
            Condition memory condition = _strategy.steps[i].condition;
            if (condition.conditionAddress != address(0)) {
                _changeStrategyInCondition(msg.sender, condition.conditionAddress, condition.id, id, false);
            }
        }

        delete strategies[storageId];

        emit StrategyDeleted(msg.sender, id);
    }

    /// @inheritdoc IStrategyBuilderModule
    function executeStrategy(uint32 id) external strategyExist(msg.sender, id) nonReentrant {
        _executeStrategy(msg.sender, id);
    }

    /// @inheritdoc IStrategyBuilderModule
    function createAutomation(
        uint32 id,
        uint32 strategyId,
        address paymentToken,
        uint256 maxFeeInUSD,
        Condition calldata condition
    ) external automationDoesNotExist(msg.sender, id) strategyExist(msg.sender, strategyId) {
        //Specific validations
        _validatePaymentToken(paymentToken);

        _validateCondition(condition);

        _changeAutomationInCondition(msg.sender, condition.conditionAddress, condition.id, id, true);

        bytes32 automationSID = getStorageId(msg.sender, id);
        Automation storage _newAutomation = automations[automationSID];

        _newAutomation.condition = condition;
        _newAutomation.strategyId = strategyId;

        _newAutomation.paymentToken = paymentToken;
        _newAutomation.maxFeeAmount = maxFeeInUSD;

        bytes32 strategySID = getStorageId(msg.sender, strategyId);
        strategiesUsed[strategySID].push(id);
        automationsToIndex[automationSID] = uint32(strategiesUsed[strategySID].length - 1);

        emit AutomationCreated(msg.sender, id, strategyId, condition, paymentToken, maxFeeInUSD);
    }

    /// @inheritdoc IStrategyBuilderModule
    function deleteAutomation(uint32 id) external automationExist(msg.sender, id) {
        _deleteAutomation(msg.sender, id);
    }

    /// @inheritdoc IStrategyBuilderModule
    function executeAutomation(uint32 id, address wallet, address beneficary)
        external
        automationExist(wallet, id)
        nonReentrant
    {
        bytes32 automationSID = getStorageId(wallet, id);
        Automation memory _automation = automations[automationSID];

        //Check the condition
        (uint8 conditionResult,) = _checkCondition(wallet, _automation.condition);

        if (conditionResult == 0) {
            revert AutomationNotExecutable(_automation.condition.conditionAddress, _automation.condition.id);
        }

        uint256 feeInUSD = _executeStrategy(wallet, _automation.strategyId);

        if (feesEnabled && feeInUSD > _automation.maxFeeAmount) {
            revert FeeExceedMaxFee();
        }

        address _strategyCreator = strategies[getStorageId(wallet, _automation.strategyId)].creator;
        uint256 feeInToken =
            feeInUSD > 0 ? _payAutomation(wallet, _automation.paymentToken, feeInUSD, beneficary, _strategyCreator) : 0;

        _updateCondition(wallet, _automation.condition, id);

        emit AutomationExecuted(wallet, id, _automation.paymentToken, feeInToken, feeInUSD);
    }

    function storeConextVariable(bytes32 contextId, bytes32 key, ParamType paramType, bytes memory value) external {
        if (!_hasValidKey(key)) revert InvalidContextKey();

        ActionContext storage context = globalContexts[msg.sender][contextId];

        _storeParamInContext(context, key, paramType, value);

        emit ContextVariableStored(contextId, key, value);
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃       Context functions         ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /**
     * @dev Process action parameters by replacing values at specified offsets
     */
    function _processActionParameters(Action memory action, ActionContext storage context)
        internal
        view
        returns (bytes memory)
    {
        if (action.inputs.length == 0) {
            return action.parameter;
        }

        bytes memory processedParams = action.parameter;

        // Process each input replacement
        for (uint256 i = 0; i < action.inputs.length; i++) {
            ContextKey memory input = action.inputs[i];

            if (_hasValidKey(input.key)) {
                bytes memory replacementValue =
                    _getContextValueByType(context, input.key, input.parameterReplacement.paramType);

                if (replacementValue.length > 0) {
                    processedParams =
                        _replaceParameterAtOffset(processedParams, input.parameterReplacement, replacementValue);
                }
            }
        }

        return processedParams;
    }

    /**
     * @dev Get context value by type from global storage
     */
    function _getContextValueByType(ActionContext storage context, bytes32 key, ParamType paramType)
        internal
        view
        returns (bytes memory)
    {
        if (paramType == ParamType.UINT256) {
            uint256 amount = context.amounts[key];
            if (amount > 0 || context.variables[key].length > 0) {
                return amount > 0 ? abi.encode(amount) : context.variables[key];
            }
        } else if (paramType == ParamType.ADDRESS) {
            address addr = context.addresses[key];
            if (addr != address(0)) {
                return abi.encode(addr);
            }
        } else if (paramType == ParamType.BOOL) {
            // Check if boolean was explicitly set
            if (context.variables[key].length > 0) {
                bool value = context.booleans[key];
                return abi.encode(value);
            }
        } else if (paramType == ParamType.BYTES32) {
            bytes memory data = context.variables[key];
            if (data.length >= 32) {
                return data;
            }
        }

        // Fallback to raw variables
        return context.variables[key];
    }

    /**
     * @dev Replace parameter value at specific offset
     */
    function _replaceParameterAtOffset(bytes memory parameters, Parameter memory param, bytes memory replacement)
        internal
        pure
        returns (bytes memory)
    {
        require(param.offset + param.length <= parameters.length, "Invalid parameter offset");
        require(replacement.length >= param.length, "Replacement too short");

        // Replace bytes at the specified offset
        for (uint256 i = 0; i < param.length; i++) {
            parameters[param.offset + i] = replacement[i];
        }

        return parameters;
    }

    function _storeToGlobalContext(address wallet, bytes32 contextId, ContextKey memory outputKey, bytes memory result)
        internal
    {
        if (!_hasValidKey(outputKey.key)) return;

        ActionContext storage globalContext = globalContexts[wallet][contextId];

        require(
            outputKey.parameterReplacement.offset + outputKey.parameterReplacement.length <= result.length,
            "Slice out of bounds"
        );

        // ---- SIMPLE BYTE SLICE ----
        bytes memory sliced = new bytes(outputKey.parameterReplacement.length);
        for (uint256 i; i < outputKey.parameterReplacement.length; i++) {
            sliced[i] = result[outputKey.parameterReplacement.offset + i];
        }

        // Store raw result
        globalContext.variables[outputKey.key] = sliced;

        _storeParamInContext(globalContext, outputKey.key, outputKey.parameterReplacement.paramType, sliced);
        // BYTES32 is stored as raw variables

        emit ContextVariableStored(contextId, outputKey.key, sliced);
    }

    function _storeParamInContext(ActionContext storage context, bytes32 key, ParamType paramType, bytes memory result)
        internal
    {
        if (paramType == ParamType.UINT256) {
            if (result.length >= 32) {
                uint256 value = abi.decode(result, (uint256));
                context.amounts[key] = value;
            }
        } else if (paramType == ParamType.ADDRESS) {
            if (result.length >= 32) {
                address addr = abi.decode(result, (address));
                context.addresses[key] = addr;
            }
        } else if (paramType == ParamType.BOOL) {
            if (result.length >= 32) {
                bool value = abi.decode(result, (bool));
                context.booleans[key] = value;
            }
        }
    }

    function _hasValidKey(bytes32 key) internal pure returns (bool) {
        return key != bytes32(0);
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃       Internal functions         ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    function _createStrategy(uint32 id, address creator, StrategyStep[] calldata steps, bytes32 contextId)
        internal
        strategyDoesNotExist(msg.sender, id)
    {
        _validateSteps(steps);

        Strategy storage newStrategy = strategies[getStorageId(msg.sender, id)];

        newStrategy.creator = creator;

        newStrategy.contextId = contextId == bytes32(0)
            ? keccak256(abi.encodePacked(msg.sender, id, block.timestamp, block.number))
            : contextId;

        for (uint256 i = 0; i < steps.length; i++) {
            StrategyStep memory step = steps[i];

            if (step.condition.conditionAddress != address(0)) {
                // Validate the condition
                _validateCondition(step.condition);

                _changeStrategyInCondition(msg.sender, step.condition.conditionAddress, step.condition.id, id, true);
            }

            // Create a new step in storage
            StrategyStep storage newStep = newStrategy.steps.push();
            newStep.condition = step.condition;

            // Loop through the actions and add them to the step
            for (uint256 j = 0; j < step.actions.length; j++) {
                _validateAction(step.actions[j]);

                Action memory _currAction = step.actions[j];
                Action storage newAction = newStep.actions.push();

                newAction.target = _currAction.target;
                newAction.parameter = _currAction.parameter;
                newAction.value = _currAction.value;
                newAction.selector = _currAction.selector;
                newAction.actionType = _currAction.actionType;

                newAction.output = _currAction.output;
                newAction.result = _currAction.result;

                // Save the input keys for this action into the new step's actions
                // Create a copy of the input keys array
                uint256 inputCount = step.actions[j].inputs.length;
                for (uint256 k = 0; k < inputCount; k++) {
                    newAction.inputs.push(step.actions[j].inputs[k]);
                }
            }
        }

        emit StrategyCreated(msg.sender, id, creator, newStrategy.contextId, newStrategy);
    }

    function _executeStrategy(address wallet, uint32 id) internal returns (uint256 fee) {
        fee = _executeStep(wallet, id, 0, getStorageId(wallet, id));

        emit StrategyExecuted(wallet, id);
    }

    function _executeStep(address wallet, uint32 id, uint16 index, bytes32 strategyId) internal returns (uint256 fee) {
        StrategyStep memory _step = strategies[strategyId].steps[index];

        //Check Condition
        (uint8 conditionResult, uint16 nextIndex) = _checkCondition(wallet, _step.condition);

        if (conditionResult == 1) {
            //Execute all actions from the step
            for (uint256 i = 0; i < _step.actions.length; i++) {
                uint256 _actionFee = _executeAction(wallet, _step.actions[i], strategies[strategyId].contextId);
                fee += _actionFee;
            }

            emit StrategyStepExecuted(wallet, id, index, _step.actions);
        }

        if (nextIndex != 0) {
            //if there is a next step go to it
            uint256 _feeNextStep = _executeStep(wallet, id, nextIndex, strategyId);
            fee += _feeNextStep;
        }
    }

    function _executeAction(address _wallet, Action memory _action, bytes32 contextId)
        internal
        returns (uint256 feeInUSD)
    {
        if (!feesEnabled) {
            _execute(_wallet, _action, contextId);
            emit ActionExecuted(_wallet, _action);
            return 0; // No fee calculation or emission if disabled
        }

        (address tokenToTrack, bool exist) =
            feeController.getTokenForAction(_action.target, _action.selector, _action.parameter);
        // If the volume token exist track the volume before and after the execution, else get the min fee

        uint256 preExecBalance = exist ? IERC20(tokenToTrack).balanceOf(_wallet) : 0;

        _execute(_wallet, _action, contextId);

        IFeeController.FeeType feeType = feeController.functionFeeConfig(_action.selector).feeType;

        if (exist) {
            uint256 postExecBalance = IERC20(tokenToTrack).balanceOf(_wallet);
            uint256 volume = feeType == IFeeController.FeeType.Deposit
                ? preExecBalance - postExecBalance
                : postExecBalance - preExecBalance;

            feeInUSD = feeController.calculateFee(tokenToTrack, _action.selector, volume);
        } else {
            feeInUSD = feeController.minFeeInUSD(feeType);
        }

        emit ActionExecuted(_wallet, _action);
    }

    function _execute(address _wallet, Action memory _action, bytes32 contextId) internal {
        bytes memory executionParams = _action.parameter;
        if (_action.inputs.length > 0) {
            executionParams = _processActionParameters(_action, globalContexts[_wallet][contextId]);
        }

        bytes memory data =
            _action.selector == bytes4(0) ? bytes("") : abi.encodePacked(_action.selector, executionParams);

        bytes memory executionResult;
        if (_action.actionType == ActionType.EXTERNAL) {
            executionResult = IModularAccount(_wallet).execute(_action.target, _action.value, data);
        } else {
            (, bytes memory _result) = _action.target.call(data);

            bool hasStoreResult = _hasStoreResult(_result);

            if (hasStoreResult) {
                (IAction.PluginExecution[] memory executions, bytes memory actionCallResult) =
                    abi.decode(_result, (IAction.PluginExecution[], bytes));

                executionResult = _executePluginsAndGetResult(_wallet, executions, _action.result, actionCallResult);
            } else {
                IAction.PluginExecution[] memory executions = abi.decode(_result, (IAction.PluginExecution[]));

                executionResult = _executePluginsAndGetResult(_wallet, executions, _action.result, "");
            }
        }

        if (_action.output.key != bytes32(0)) {
            _storeToGlobalContext(_wallet, contextId, _action.output, executionResult);
        }
    }

    function _hasStoreResult(bytes memory data) internal pure returns (bool) {
        // Check if the data starts with a tuple containing 2 elements
        // This is a simplified check - you might want more robust detection
        if (data.length < 64) return false;

        // Try to peek at the structure
        uint256 firstOffset;
        uint256 secondOffset;

        assembly {
            firstOffset := mload(add(data, 0x20)) // First element offset
            secondOffset := mload(add(data, 0x40)) // Second element offset
        }

        // If we have two valid offsets, it's likely a tuple with 2 elements
        return firstOffset > 0 && secondOffset > firstOffset;
    }

    function _executePluginsAndGetResult(
        address _wallet,
        IAction.PluginExecution[] memory executions,
        uint256 resultIndex,
        bytes memory actionCallResult
    ) internal returns (bytes memory) {
        require(resultIndex <= executions.length, "Invalid execution index");

        bytes memory result;
        for (uint256 i = 0; i < executions.length; i++) {
            bytes memory _executionResult =
                IModularAccount(_wallet).execute(executions[i].target, executions[i].value, executions[i].data);

            if (resultIndex == i + 1) {
                result = _executionResult;
            }
        }

        return resultIndex == 0 ? actionCallResult : result;
    }

    function _deleteAutomation(address wallet, uint32 id) internal {
        bytes32 automationSID = getStorageId(wallet, id);
        Automation memory _automation = automations[automationSID];

        uint32[] storage _usedInAutomations = strategiesUsed[getStorageId(wallet, _automation.strategyId)];

        uint32 _actualAutomationIndex = automationsToIndex[automationSID];
        uint256 _lastAutomationIndex = _usedInAutomations.length - 1;
        if (_actualAutomationIndex != _lastAutomationIndex) {
            uint32 _lastAutomation = _usedInAutomations[_lastAutomationIndex];
            _usedInAutomations[_actualAutomationIndex] = _lastAutomation;
            automationsToIndex[getStorageId(wallet, _lastAutomation)] = _actualAutomationIndex;
        }
        _usedInAutomations.pop();

        _changeAutomationInCondition(
            wallet, _automation.condition.conditionAddress, _automation.condition.id, id, false
        );

        delete automations[automationSID];
        delete automationsToIndex[automationSID];

        emit AutomationDeleted(wallet, id);
    }

    function _checkCondition(address _wallet, Condition memory _condition)
        internal
        view
        returns (uint8 conditionResult, uint16 nextStep)
    {
        if (_condition.conditionAddress == address(0)) {
            nextStep = _condition.result1;
            conditionResult = 1;
        } else {
            conditionResult = ICondition(_condition.conditionAddress).checkCondition(_wallet, _condition.id);
            if (conditionResult == 1) {
                nextStep = _condition.result1;
            } else {
                nextStep = _condition.result0;
            }
        }
    }

    function _changeAutomationInCondition(
        address _wallet,
        address _condition,
        uint32 _conditionId,
        uint32 automationId,
        bool _add
    ) internal {
        if (!ICondition(_condition).conditionInAutomation(_wallet, _conditionId, automationId) == _add) {
            bytes memory data = _add
                ? abi.encodeCall(ICondition.addAutomationToCondition, (_conditionId, automationId))
                : abi.encodeCall(ICondition.removeAutomationFromCondition, (_conditionId, automationId));

            bytes memory result = IModularAccount(_wallet).execute(_condition, 0, data);
            bool _success = abi.decode(result, (bool));
            if (!_success) revert changeAutomationInConditionFailed();
        }
    }

    function _changeStrategyInCondition(
        address _wallet,
        address _condition,
        uint32 _conditionId,
        uint32 _strategy,
        bool _add
    ) internal {
        if (!ICondition(_condition).conditionInStrategy(_wallet, _conditionId, _strategy) == _add) {
            bytes memory data = _add
                ? abi.encodeCall(ICondition.addStrategyToCondition, (_conditionId, _strategy))
                : abi.encodeCall(ICondition.removeStrategyFromCondition, (_conditionId, _strategy));

            bytes memory result = IModularAccount(_wallet).execute(_condition, 0, data);
            bool _success = abi.decode(result, (bool));
            if (!_success) revert ChangeStrategyInConditionFailed();
        }
    }

    function _payAutomation(
        address wallet,
        address paymentToken,
        uint256 feeInUSD,
        address beneficiary,
        address creator
    ) internal returns (uint256) {
        if (feeInUSD == 0) {
            return 0; // Early return for zero or disabled fees
        }

        uint256 feeInToken = feeController.calculateTokenAmount(paymentToken, feeInUSD);

        if (feeInToken == 0) return 0;

        if (paymentToken != address(0)) {
            bytes memory _approveData = abi.encodeCall(IERC20.approve, (address(feeHandler), feeInToken));
            IModularAccount(wallet).execute(paymentToken, 0, _approveData);
        }

        bytes memory _handleFeeData = paymentToken != address(0)
            ? abi.encodeCall(IFeeHandler.handleFee, (paymentToken, feeInToken, beneficiary, creator))
            : abi.encodeCall(IFeeHandler.handleFeeETH, (beneficiary, creator));

        bytes memory paymentResult = IModularAccount(wallet).execute(
            address(feeHandler), paymentToken == address(0) ? feeInToken : 0, _handleFeeData
        );

        uint256 totalFee = abi.decode(paymentResult, (uint256));
        return totalFee;
    }

    function _updateCondition(address _wallet, Condition memory _condition, uint32 automationId) internal {
        if (ICondition(_condition.conditionAddress).isUpdateable(_wallet, _condition.id)) {
            bytes memory _data = abi.encodeCall(ICondition.updateCondition, (_condition.id));
            bytes memory _result = IModularAccount(_wallet).execute(_condition.conditionAddress, 0, _data);
            bool _success = abi.decode(_result, (bool));
            if (!_success) revert UpdateConditionFailed(_condition.conditionAddress, _condition.id);
        } else {
            _deleteAutomation(_wallet, automationId);
        }
    }

    function _validatePaymentToken(address token) internal view {
        bool valid = true;
        if (!feeController.hasOracle(token)) {
            valid = false;
        }

        if (!feeHandler.tokenAllowed(token)) {
            valid = false;
        }

        if (!valid) {
            revert PaymentTokenNotAllowed();
        }
    }

    function _validateSteps(StrategyStep[] memory steps) internal pure {
        uint256 stepsLength = steps.length;
        if (stepsLength == 0) {
            revert InvalidStepArrayLength();
        }
        for (uint256 i = 0; i < stepsLength; i++) {
            _validateStep(steps[i], stepsLength, i);
        }
    }

    function _validateStep(StrategyStep memory step, uint256 maxStepIndex, uint256 stepIndex) internal pure {
        if (step.condition.result0 >= maxStepIndex || step.condition.result1 >= maxStepIndex) {
            revert InvalidNextStepIndex();
        }

        if (step.condition.conditionAddress == address(0) && step.actions.length == 0) {
            revert NoConditionOrActions(stepIndex);
        }
    }

    function _validateAction(Action memory action) internal view {
        if (action.actionType == ActionType.INTERNAL_ACTION) {
            if (!actionRegistry.isAllowed(action.target)) {
                revert InvalidActionTarget();
            }

            if (action.target.code.length == 0) {
                revert InvalidActionTarget();
            }
            try IERC165(action.target).supportsInterface(type(IAction).interfaceId) returns (bool valid) {
                if (!valid) {
                    revert InvalidActionTarget();
                }
            } catch {
                revert InvalidActionTarget();
            }
        } else {
            if (action.target == address(0)) {
                revert InvalidActionTarget();
            }
        }
    }

    function _validateCondition(Condition memory condition) internal view {
        if (condition.conditionAddress != address(0)) {
            if (condition.conditionAddress.code.length == 0) {
                revert InvalidConditionAddress();
            }
            try IERC165(condition.conditionAddress).supportsInterface(type(ICondition).interfaceId) returns (bool valid)
            {
                if (!valid) {
                    revert InvalidCondition();
                }
            } catch {
                revert InvalidCondition();
            }
        }
    }

    function _decodePluginExecutions(bytes memory encodedData)
        private
        pure
        returns (IAction.PluginExecution[] memory)
    {
        return abi.decode(encodedData, (IAction.PluginExecution[]));
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃    Plugin interface functions    ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    function onInstall(bytes calldata) external pure override {}

    function onUninstall(bytes calldata) external pure override {}

    function moduleId() external pure returns (string memory) {
        return "pecunity.strategy-builder-module";
    }

    function executionManifest() external pure returns (ExecutionManifest memory) {
        ExecutionManifest memory manifest;

        ManifestExecutionFunction[] memory executionFunctions = new ManifestExecutionFunction[](6);
        // 1. Publicly callable
        executionFunctions[0] = ManifestExecutionFunction({
            executionSelector: this.executeAutomation.selector,
            skipRuntimeValidation: true,
            allowGlobalValidation: false
        });

        // 2. Internal-only functions
        executionFunctions[1] = ManifestExecutionFunction({
            executionSelector: this.createStrategy.selector,
            skipRuntimeValidation: false,
            allowGlobalValidation: true
        });

        executionFunctions[2] = ManifestExecutionFunction({
            executionSelector: this.deleteStrategy.selector,
            skipRuntimeValidation: false,
            allowGlobalValidation: true
        });

        executionFunctions[3] = ManifestExecutionFunction({
            executionSelector: this.createAutomation.selector,
            skipRuntimeValidation: false,
            allowGlobalValidation: true
        });

        executionFunctions[4] = ManifestExecutionFunction({
            executionSelector: this.deleteAutomation.selector,
            skipRuntimeValidation: false,
            allowGlobalValidation: true
        });

        executionFunctions[5] = ManifestExecutionFunction({
            executionSelector: this.executeStrategy.selector,
            skipRuntimeValidation: false,
            allowGlobalValidation: true
        });

        manifest.executionFunctions = executionFunctions;

        return manifest;
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃    External View Functions       ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @inheritdoc IStrategyBuilderModule
    function strategy(address wallet, uint32 id) external view returns (Strategy memory) {
        return strategies[getStorageId(wallet, id)];
    }

    /// @inheritdoc IStrategyBuilderModule
    function automation(address wallet, uint32 id) external view returns (Automation memory) {
        return automations[getStorageId(wallet, id)];
    }

    /// @inheritdoc IStrategyBuilderModule
    function getStorageId(address wallet, uint32 id) public pure returns (bytes32) {
        return keccak256(abi.encodePacked(wallet, id));
    }

    function supportsInterface(bytes4 interfaceId) public view virtual returns (bool) {
        return interfaceId == type(IStrategyBuilderModule).interfaceId;
    }

    function getContextVariable(address wallet, bytes32 contextId, bytes32 key) external view returns (bytes memory) {
        return globalContexts[wallet][contextId].variables[key];
    }
}

